{
  "packet_id": "H6-T01-1",
  "claim_id": "C049",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C049.component",
    "value": "Workload can create or conceal apparent temporal patterns.",
    "scope": "A possible interpretive limitation; the mapping does not specify the relevant workload measure or mechanism.",
    "provenance": {
      "refs": [
        {
          "source_id": "P024",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span explicitly includes workload among factors that can create or hide patterns."
    }
  },
  "signal_basis": {
    "component_id": "C049.signal_basis",
    "value": "Comparable turnaround observations summarized through late-start rates, delay minutes and stage-specific counts exhibit repeated delays, trends, reversals or recovery after isolated spikes.",
    "scope": "Temporal observations assumed to occur for this judgment; the mapping describes signals to seek, not established findings.",
    "provenance": {
      "refs": [
        {
          "source_id": "P007",
          "role": "SUPPORT"
        },
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P015",
          "role": "SUPPORT"
        },
        {
          "source_id": "P018",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply comparable recording, temporal summaries, the candidate patterns and their prospective status."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C049.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported as a possible limitation, without requiring a conditional empirical warrant."
    }
  },
  "rationale": "Workload variation can change demand relative to available capacity, producing delay patterns or masking changes in turnaround performance. Repeated comparable measurement does not by itself exclude this influence. This licenses the stated possibility, without establishing that workload actually distorted the observed sequence.",
  "uncertainty": "The mapping does not establish whether workload affected these bookings, its magnitude or its mechanism; the claim does not assert those particulars.",
  "anomalies": []
}
